import{_ as e,o as t,c as o,a2 as c}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"配置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/config.md","filePath":"guide/config.md","lastUpdated":1793803670000}'),a={name:"guide/config.md"};function r(i,d,l,s,n,_){return t(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h1><p><code>config.json</code> 声明 LLM 连接、权限策略与启用的插件：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>providers</code></td><td>对象</td><td>LLM 供应商集合，每项含 <code>base_url</code> 与 <code>api_key</code>。</td></tr><tr><td><code>llm.provider</code></td><td>字符串</td><td>选用哪个 provider 的键名。</td></tr><tr><td><code>llm.model</code></td><td>字符串</td><td>模型名。</td></tr><tr><td><code>tools.permission</code></td><td><code>read_only</code> / <code>standard</code> / <code>full</code></td><td>权限档位：只读拦截写工具；标准档位对高风险工具做交互式确认；完全档位放行。</td></tr><tr><td><code>tools.workspace_restrict</code></td><td>bool</td><td>工作区路径白名单开关。开启后工具只能在会话/工作区内读写，越界（绝对路径、<code>..</code>、符号链接逃逸）被拒绝。</td></tr><tr><td><code>session.dir</code></td><td>字符串</td><td>会话 JSONL 存放目录（默认内核 DataDir 下的 <code>sessions/</code>）。</td></tr><tr><td><code>plugins</code></td><td>字符串数组</td><td>启用的插件名列表，如 <code>session</code> / <code>tools</code> / <code>loop</code> / <code>tui</code> / <code>web</code> / <code>repl</code>。</td></tr></tbody></table><h2 id="权限三档" tabindex="-1">权限三档 <a class="header-anchor" href="#权限三档" aria-label="Permalink to &quot;权限三档&quot;">​</a></h2><ul><li><code>read_only</code>：guard 直接拦截所有写工具，最安全。</li><li><code>standard</code>（默认）：读工具直放，写工具执行前交互式确认。</li><li><code>full</code>：全部放行，不做确认——仅在你完全信任输入时用。</li></ul><h2 id="工作区白名单" tabindex="-1">工作区白名单 <a class="header-anchor" href="#工作区白名单" aria-label="Permalink to &quot;工作区白名单&quot;">​</a></h2><p>开启 <code>workspace_restrict</code> 后，文件类工具会做两层检查（静态路径相对计算 + 解析符号链接后的祖先校验），阻止通过 <code>../</code> 或符号链接逃逸出工作区。运行期可经 Web API 开关。</p>',7)])])}const u=e(a,[["render",r]]);export{h as __pageData,u as default};
